class Component extends DCLogic {
  state = { qty: 2, pay: 'esp', step: 3 };
  fmt(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' Ar'; }
  payRow(active) {
    return 'background:#fff;border-radius:18px;padding:14px;display:flex;gap:12px;align-items:center;border:1.5px solid ' +
      (active ? '#E8342A' : '#E9E5E0') + (active ? ';box-shadow:0 2px 10px rgba(232,52,42,.14)' : '') + ';cursor:pointer';
  }
  payIco(active) { return 'font-size:22px;color:' + (active ? '#E8342A' : '#DCD8D3'); }
  dot(i) {
    const s = this.state.step;
    const done = i <= s, cur = i === s;
    const bg = done ? (cur ? '#E8342A' : '#16A34A') : '#EDE9E4';
    return 'width:26px;height:26px;border-radius:999px;flex:none;display:flex;align-items:center;justify-content:center;background:' + bg +
      (done ? '' : ';color:transparent') + (cur ? ';box-shadow:0 0 0 5px rgba(232,52,42,.16)' : '');
  }
  line(i) {
    return 'width:2px;flex:1;min-height:26px;background:' + (i < this.state.step ? '#16A34A' : '#EDE9E4');
  }
  renderVals() {
    const p = this.state.pay;
    const steps = [
      ['inbox', 'Commande reçue', 'Le restaurant va confirmer dans un instant'],
      ['restaurant', 'Confirmée', 'Préparation dans environ 20 minutes'],
      ['soup_kitchen', 'En préparation', 'Vos pizzas sont au four'],
      ['two_wheeler', 'En livraison', 'Arrivée estimée 10h15 – 10h30'],
      ['check_circle', 'Livrée', 'Bon appétit ! Merci pour votre commande']
    ][this.state.step];
    return {
      qty: this.state.qty,
      qtyTotal: this.fmt(this.state.qty * 34000),
      inc: () => this.setState(s => ({ qty: Math.min(20, s.qty + 1) })),
      dec: () => this.setState(s => ({ qty: Math.max(1, s.qty - 1) })),
      pickCb: () => this.setState({ pay: 'cb' }),
      pickEsp: () => this.setState({ pay: 'esp' }),
      pickOm: () => this.setState({ pay: 'om' }),
      styCb: this.payRow(p === 'cb'), styEsp: this.payRow(p === 'esp'), styOm: this.payRow(p === 'om'),
      icoCb: this.payIco(p === 'cb'), icoEsp: this.payIco(p === 'esp'), icoOm: this.payIco(p === 'om'),
      radCb: p === 'cb' ? 'radio_button_checked' : 'radio_button_unchecked',
      radEsp: p === 'esp' ? 'radio_button_checked' : 'radio_button_unchecked',
      radOm: p === 'om' ? 'radio_button_checked' : 'radio_button_unchecked',
      payLabel: p === 'cb' ? 'carte bancaire' : p === 'om' ? 'Orange Money' : 'espèces',
      stepIcon: steps[0], stepTitle: steps[1], stepSub: steps[2],
      setStep0: () => this.setState({ step: 0 }), setStep1: () => this.setState({ step: 1 }),
      setStep2: () => this.setState({ step: 2 }), setStep3: () => this.setState({ step: 3 }),
      setStep4: () => this.setState({ step: 4 }),
      dot0: this.dot(0), dot1: this.dot(1), dot2: this.dot(2), dot3: this.dot(3), dot4: this.dot(4),
      line0: this.line(0), line1: this.line(1), line2: this.line(2), line3: this.line(3)
    };
  }
}
